function ff_anychecked(element, message) {
  var name = '';
  var cnt = 0;

  /* --- CAS : collection d'éléments (plusieurs radios / checkboxes) --- */
  if (!element.name) {
    if (element.length && element.length !== 0) {
      name = element[0].name;
      var i = 0;

      while (i !== element.length) {
        if (element[i].name === name && element[i].checked) {
          cnt++;
        }
        i++;
      }

      if (cnt === 0) {
        ff_validationFocus(element[0].name);
        if (message === '') {
          message = "Please check or select " + name + ".\n";
        }
        return message;
      }
      return '';
    }
    return '';
  }

  /* --- CAS : UN SEUL élément radio / checkbox --- */
  name = element.name;

  if (name.substr(0, 6) === 'ff_nm_') {
    name = name.substring(6, name.length - 2);
  }

  if (typeof element.checked !== 'undefined') {
    if (!element.checked) {
      ff_validationFocus(element.name);
      if (message === '') {
        message = "Please check or select " + name + ".\n";
      }
      return message;
    }
    return '';
  }

  /* --- CAS : gestion via ff_elements (fallback legacy) --- */
  cnt = 0;
  var i = 0;

  while (i !== ff_elements.length) {
    if (ff_elements[i][2] === name) {
      if (ff_getElementByIndex(i).checked) {
        cnt++;
      }
    }
    i++;
  }

  if (cnt === 0) {
    ff_validationFocus(element.name);
    if (message === '') {
      message = "Please check or select " + name + ".\n";
    }
    return message;
  }

  return '';
}

function ff_checked(element, message)
{
    if (element.checked) 
        return ''; 
    else {
        if (message=='') message = element.name+" is not checked.\n";
        ff_validationFocus(element.name);
        return message;
    } 
}

function ff_resetForm(element, action) {
    // Accéder au formulaire directement par son ID sans utiliser eval
    var form = document.getElementById(ff_processor.form_id);
    
    // Si le formulaire est trouvé, le réinitialiser
    if (form) {
        form.reset();
    } else {
        console.error('Formulaire non trouvé avec l\'ID:', ff_processor.form_id);
    }
}
