var bfQuoteBase = {'Showcase website': 900, 'Online shop': 2500, 'Website redesign': 1200};
var bfQuoteOptions = {'SEO': 300, 'Multilingual': 400, 'Annual maintenance': 240};
function bfQuoteEstimate() {
  var total = bfQuoteBase[bfField('ProjectType')] || 0;
  var chosen = String(bfField('Options') || '');
  for (var option in bfQuoteOptions) {
    if (chosen.indexOf(option) !== -1) { total += bfQuoteOptions[option]; }
  }
  ff_getElementByName('Estimate').value = total;
  if (typeof populateSummarizers === 'function') { populateSummarizers(); }
}
function ff_ProjectType_action(element, action) { bfQuoteEstimate(); }
